    when(mockLockService.tryUpsertLockFile(any(), eq(Option.empty()))).thenReturn(Pair.of(LockUpsertResult.SUCCESS, Option.of(realLockFile)));
    when(mockHeartbeatManager.startHeartbeatForThread(any())).thenReturn(true);
    when(mockHeartbeatManager.stopHeartbeat(true)).thenReturn(true);
    when(mockHeartbeatManager.hasActiveHeartbeat()).thenReturn(false);
    when(mockLockService.tryUpsertLockFile(any(), eq(Option.of(realLockFile)))).thenReturn(Pair.of(LockUpsertResult.SUCCESS, Option.of(new StorageLockFile(new StorageLockData(true, data.getValidUntil(), ownerId), "v2"))));
    assertTrue(lockProvider.tryLock());
    when(mockHeartbeatManager.hasActiveHeartbeat()).thenReturn(// when we try to stop the heartbeat we will check if heartbeat is active return true.
    true).thenReturn(// when try to set lock to expire we will assert no active heartbeat as a precondition.
    false);
    lockProvider.unlock();
    assertNull(lockProvider.getLock());
    lockProvider.unlock();
}

