    when(auditMockClient.readCurrentLockFile()).thenReturn(Pair.of(LockGetResult.NOT_EXISTS, Option.empty()));
    // Mock writeObject method to return true for audit file writes
    when(auditMockClient.writeObject(anyString(), anyString())).thenReturn(true);
