private static HoodieCleanerPlan mockLastCleanCommit(HoodieTable hoodieTable, String timestamp, String earliestCommitToRetain, HoodieActiveTimeline activeTimeline, HoodieCleanMetadata cleanMetadata, Set<String> savepointsTrackedInLastClean) throws IOException {
