protected List<HoodieRecord<IndexedRecord>> dedupForCopyOnWriteStorage(HoodieWriteConfig writeConfig, HoodieData<HoodieRecord> records, boolean isGlobal, int additionalParallelism, int expectedNumPartitions) {
    HoodieIndex index = mock(HoodieIndex.class);
    when(index.isGlobal()).thenReturn(isGlobal);
    int dedupParallelism = records.getNumPartitions() + additionalParallelism;
    BaseHoodieWriteClient writeClient = getHoodieWriteClient(writeConfig);
    HoodieReaderContext readerContext = writeClient.getEngineContext().getReaderContextFactoryForWrite(metaClient, HoodieRecord.HoodieRecordType.AVRO, writeConfig.getProps()).getContext();
    List<String> orderingFieldNames = getOrderingFieldNames(readerContext.getMergeMode(), metaClient);
    BufferedRecordMerger<HoodieRecord> recordMerger = BufferedRecordMergerFactory.create(readerContext, metaClient.getTableConfig().getRecordMergeMode(), false, Option.ofNullable(writeClient.getConfig().getRecordMerger()), Option.ofNullable(writeClient.getConfig().getPayloadClass()), new Schema.Parser().parse(writeClient.getConfig().getSchema()), writeClient.getConfig().getProps(), metaClient.getTableConfig().getPartialUpdateMode());
    HoodieData<HoodieRecord<IndexedRecord>> dedupedRecsRdd = (HoodieData<HoodieRecord<IndexedRecord>>) HoodieWriteHelper.newInstance().deduplicateRecords(records, index, dedupParallelism, writeConfig.getSchema(), writeConfig.getProps(), recordMerger, readerContext, orderingFieldNames.toArray(new String[0]));
    assertEquals(expectedNumPartitions, dedupedRecsRdd.getNumPartitions());
    List<HoodieRecord<IndexedRecord>> dedupedRecs = dedupedRecsRdd.collectAsList();
    assertEquals(isGlobal ? 1 : 2, dedupedRecs.size());
    assertNoDupesWithinPartition(dedupedRecs);
    return dedupedRecs;
}

