    StreamerCheckpointV2 translatedCheckpoint = CheckpointUtils.convertToCheckpointV2ForCommitTime(checkpoint, metaClient, FAIL);
    assertEquals(completionTime, translatedCheckpoint.getCheckpointKey());
}

