private SeekableDataInputStream prepareMockedLogInputStream(int contentSize, int numReadFailTimes) throws IOException {
    IOException exception = new IOException("Read content from log file fails");
    Answer<Integer> mockedContentAnswer = modifyContentWithRead(contentSize);
    InputStream stream = mock(InputStream.class);
    switch(numReadFailTimes) {
        case 0:
            when(stream.read(any(), eq(0), eq(contentSize))).thenAnswer(mockedContentAnswer);
            break;
        case 1:
            when(stream.read(any(), eq(0), eq(contentSize))).thenThrow(exception).thenAnswer(mockedContentAnswer);
            break;
        case 2:
            when(stream.read(any(), eq(0), eq(contentSize))).thenThrow(exception).thenThrow(exception).thenAnswer(mockedContentAnswer);
            break;
        case 3:
            when(stream.read(any(), eq(0), eq(contentSize))).thenThrow(exception).thenThrow(exception).thenThrow(exception).thenAnswer(mockedContentAnswer);
            break;
        default:
            throw new IllegalArgumentException("This mock does not support more than 3 failed read calls");
    }
    return new SeekableDataInputStream(stream) {

        @Override
        public long getPos() throws IOException {
            return 0;
        }

        @Override
        public void seek(long pos) throws IOException {
        }
    };
}

protected static KeyBasedFileGroupRecordBuffer<IndexedRecord> buildKeyBasedFileGroupRecordBuffer(HoodieReaderContext<IndexedRecord> readerContext, HoodieTableConfig tableConfig, HoodieReadStats readStats, HoodieRecordMerger recordMerger, RecordMergeMode recordMergeMode, List<String> orderingFieldNames, Option<Pair<String, String>> deleteMarkerKeyValue) {
    TypedProperties props = new TypedProperties();
    deleteMarkerKeyValue.ifPresent(markerKeyValue -> {
        props.setProperty(DELETE_KEY, markerKeyValue.getLeft());
        props.setProperty(DELETE_MARKER, markerKeyValue.getRight());
    });
    FileGroupReaderSchemaHandler<IndexedRecord> fileGroupReaderSchemaHandler = mock(FileGroupReaderSchemaHandler.class);
    when(fileGroupReaderSchemaHandler.getRequiredSchema()).thenReturn(SCHEMA);
    when(fileGroupReaderSchemaHandler.getInternalSchema()).thenReturn(InternalSchema.getEmptyInternalSchema());
    when(fileGroupReaderSchemaHandler.getDeleteContext()).thenReturn(new DeleteContext(props, SCHEMA));
    readerContext.setSchemaHandler(fileGroupReaderSchemaHandler);
    return buildKeyBasedFileGroupRecordBuffer(readerContext, tableConfig, readStats, recordMerger, recordMergeMode, orderingFieldNames, props, Option.empty());
}

