@Test
void skipUpdatingSchema_partitioned() {
    BigQuerySyncConfig config = new BigQuerySyncConfig(properties);
    client = new HoodieBigQuerySyncClient(config, mockBigQuery, metaClient);
    Table mockTable = mock(Table.class);
