@Test
void testHasCommittedLogFiles() throws Exception, InterruptedException {
    HoodieTableMetaClient metaClient = mock(HoodieTableMetaClient.class);
    when(metaClient.getBasePath()).thenReturn(new StoragePath(tempDir.toString()));
    HoodieMetadataTableValidator.Config config = new HoodieMetadataTableValidator.Config();
    config.basePath = basePath;
    config.validateLatestFileSlices = true;
    config.validateAllFileGroups = true;
    TimeGenerator timeGenerator = TimeGenerators.getTimeGenerator(HoodieTimeGeneratorConfig.defaultConfig(basePath), HadoopFSUtils.getStorageConf(jsc.hadoopConfiguration()));
    MockHoodieMetadataTableValidator validator = new MockHoodieMetadataTableValidator(jsc, config);
    Map<String, Set<String>> committedFilesMap = new HashMap<>();
    String baseInstantTime = TimelineUtils.generateInstantTime(true, timeGenerator);
    String logInstantTime = TimelineUtils.generateInstantTime(true, timeGenerator);
    String newInstantTime = TimelineUtils.generateInstantTime(true, timeGenerator);
    // Empty log file set
    assertEquals(Pair.of(false, ""), validator.hasCommittedLogFiles(storage, Collections.emptySet(), metaClient, committedFilesMap));
    // Empty log file
    HoodieLogFile logFile = new HoodieLogFile(new StoragePath(tempDir.toString(), FSUtils.makeLogFileName(UUID.randomUUID().toString(), HoodieLogFile.DELTA_EXTENSION, logInstantTime, 1, "1-0-1")));
    storage.create(logFile.getPath()).close();
    prepareTimelineAndValidate(metaClient, validator, Collections.emptyList(), logFile, committedFilesMap, Pair.of(false, ""));
    // Log file with command log block
    logFile = prepareLogFile(UUID.randomUUID().toString(), baseInstantTime, logInstantTime, false);
    prepareTimelineAndValidate(metaClient, validator, Collections.emptyList(), logFile, committedFilesMap, Pair.of(false, ""));
    // Log file with data log block
    logFile = prepareLogFile(UUID.randomUUID().toString(), baseInstantTime, logInstantTime, true);
    // Log block created by completed delta commit in active timeline
    committedFilesMap.put(logInstantTime, Collections.emptySet());
    prepareTimelineAndValidate(metaClient, validator, Collections.singletonList(INSTANT_GENERATOR.createNewInstant(HoodieInstant.State.COMPLETED, HoodieTimeline.DELTA_COMMIT_ACTION, logInstantTime)), logFile, committedFilesMap, Pair.of(false, ""));
    // Log block created by completed delta commit but not included in the commit metadata
    committedFilesMap.put(logInstantTime, new HashSet<>(Collections.singletonList(logFile.getPath().getName())));
    prepareTimelineAndValidate(metaClient, validator, Collections.singletonList(INSTANT_GENERATOR.createNewInstant(HoodieInstant.State.COMPLETED, HoodieTimeline.DELTA_COMMIT_ACTION, logInstantTime)), logFile, committedFilesMap, Pair.of(true, String.format("Log file is committed in an instant in active timeline: instantTime=%s %s", logInstantTime, logFile.getPath().toString())));
    committedFilesMap.clear();
    // Log block created by completed delta commit before active timeline starts
    prepareTimelineAndValidate(metaClient, validator, Collections.singletonList(INSTANT_GENERATOR.createNewInstant(HoodieInstant.State.COMPLETED, HoodieTimeline.DELTA_COMMIT_ACTION, newInstantTime)), logFile, committedFilesMap, Pair.of(true, String.format("Log file is committed in an instant in archived timeline: instantTime=%s %s", logInstantTime, logFile.getPath().toString())));
    // Log block created by inflight delta commit in active timeline
    prepareTimelineAndValidate(metaClient, validator, Collections.singletonList(INSTANT_GENERATOR.createNewInstant(HoodieInstant.State.INFLIGHT, HoodieTimeline.DELTA_COMMIT_ACTION, logInstantTime)), logFile, committedFilesMap, Pair.of(false, ""));
    // Log block created by a delta commit not in active timeline
    prepareTimelineAndValidate(metaClient, validator, Collections.singletonList(INSTANT_GENERATOR.createNewInstant(HoodieInstant.State.INFLIGHT, HoodieTimeline.DELTA_COMMIT_ACTION, baseInstantTime)), logFile, committedFilesMap, Pair.of(false, ""));
}

